def require_once(text: str, needle: str, label: str) -> None:
    count = text.count(needle)
    if count != 1:
        raise RuntimeError(
            f"{label}: expected exactly one match, found {count}"
        )


def main() -> int:
    if not CORE.exists():
        raise FileNotFoundError(CORE)
    if not LAUNCHER.exists():
        raise FileNotFoundError(LAUNCHER)

    core = CORE.read_text(encoding="utf-8")
    launcher = LAUNCHER.read_text(encoding="utf-8")

    if MARKER in core:
        print("Step 18 fixed market-band implementation is already installed.")
        return 0

    # The previously removed incorrect Step 18 patch must stay removed.
    if "# Step 18 additions for basketball_pipeline_final_master_test_core.py" in core:
        raise RuntimeError(
            "Old incorrect Step 18 patch is present. Refusing to stack patches."
        )

    if "import hashlib\n" not in core:
        require_once(core, "import argparse\n", "hashlib import anchor")
        core = core.replace(
            "import argparse\n",
            "import argparse\nimport hashlib\n",
            1,
        )

    require_once(core, "\ndef main() -> None:\n", "core main anchor")
    core = core.replace(
        "\ndef main() -> None:\n",
        "\n\n" + STEP18_BLOCK.rstrip() + "\n\n\ndef main() -> None:\n",
        1,
    )

    require_once(core, QUICK_OLD, "core parser anchor")
    core = core.replace(QUICK_OLD, QUICK_NEW, 1)

    require_once(core, SEASON_OLD, "core season branch anchor")
    core = core.replace(SEASON_OLD, SEASON_NEW, 1)

    require_once(launcher, LAUNCHER_OLD, "launcher provenance anchor")
    launcher = launcher.replace(LAUNCHER_OLD, LAUNCHER_NEW, 1)

    compile(core, str(CORE), "exec")
    compile(launcher, str(LAUNCHER), "exec")

    CORE.write_text(core, encoding="utf-8")
    LAUNCHER.write_text(launcher, encoding="utf-8")

    print(f"UPDATED: {CORE}")
    print(f"UPDATED: {LAUNCHER}")
    print("OLD BAD STEP 18 RESTORED: NO")
    print("markets.yaml modified: NO")
    print("Step 18 validation output contract: WNBA_MARKET_BANDS_REPORT.txt only")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
